// Medical Law & Ethics Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: case scenarios, landmark cases and federal laws not covered in Practice Test 1.
import {q, mix} from './q.js';
